import json

def transpose(grid):
    """Transpose a square grid"""
    return [[grid[j][i] for j in range(3)] for i in range(3)]

def reverse_rows(grid):
    """Reverse each row (horizontal flip)"""
    return [row[::-1] for row in grid]

def reverse_cols(grid):
    """Reverse columns order (vertical flip)"""
    return [grid[2-r] for r in range(3)]

def solve(input_grid):
    orig = input_grid
    transposed = transpose(input_grid)
    row_rev = reverse_rows(input_grid)
    flip_v = reverse_cols(input_grid)

    # Initialize 9x9 output grid
    output = [[0]*9 for _ in range(9)]

    for tr in range(3):
        for tc in range(3):
            if tr == 1 and tc == 1:
