# Otherwise use transpose

def solve_symmetry(grid):
    d1 = (grid[0][0], grid[1][1], grid[2][2])
    d2 = (grid[0][2], grid[1][1], grid[2][0])
    diag_matches = (d1[0] == d1[2]) + (d2[0] == d2[2])

    print(f"Diagonal matches: {diag_matches}")

    def transform_by_block_pos(br, bc):
        if br == 1 and bc == 1:
            return list(grid)  # Original

        orig = grid
        T = [[grid[j][i] for j in range(3)] for i in range(3)]
        H = [row[::-1] for row in grid]
        V = [grid[2-r] for r in range(3)]

        if diag_matches <= 1:
            # Use standard pattern
            if br in [0, 2] and bc == 1:
                return V
            elif bc in [0, 2] and br == 1:
                return H
            else:  # corners
                return T
        else:
            # Value-dependent: use H or V based on position parity for corners/edges too
            if (br + bc) % 2 == 0:
                return H
            else:
                return V

    return transform_by_block_pos

