def solve_final(grid):
    def transpose(m):
        return [[m[r][c] for r in range(len(m))] for c in range(len(m[0]))]

    def flip_v(m):
        return m[::-1]

    def flip_h(m):
        new_m = []
        for row in m:
            new_row = [val for val in reversed(row)]
            new_m.append(new_row)
        return new_m

    blocks = [[None]*3 for _ in range(3)]
    for br in range(3):
        for bc in range(3):  # block column
            if (br == 0 or br == 2) and (bc == 0 or bc == 2):
                blocks[br][bc] = transpose(grid)
            elif br == 0 and bc == 1:
                blocks[br][bc] = flip_v(grid)
            elif br == 2 and bc == 1:
                blocks[br][bc] = flip_v(grid)
            elif br == 1 and bc == 0:
                blocks[br][bc] = flip_h(grid)
            elif br == 1 and bc == 2:
                blocks[br][bc] = flip_h(grid)
            else:
                blocks[br][bc] = grid

    # Build 9x9 by iterating through output cell positions
    result = [[0]*9 for _ in range(9)]
    for global_r in range(9):
        for global_c in range(9):
            br = global_r // 3
            bc = global_c // 3
            lr = global_r % 3  # local row within block
            lc = global_c % 3  # local col within block

            block = blocks[br][bc]

            if (br == 0 or br == 2) and (bc == 0 or bc == 2):
                # Transpose: swap rows/cols
                result[global_r][global_c] = block[lc][lr]
            elif br == 0 and bc == 1:
                # Vertical flip
                result[global_r][global_c] = block[2-lr][lc]
            elif br == 2 and bc == 1:
                # Vertical flip
                result[global_r][global_c] = block[2-lr][lc]
            elif br == 1 and bc == 0:
                # Horizontal flip
                result[global_r][global_c] = block[lr][2-lc]
            elif br == 1 and bc == 2:
                # Horizontal flip
                result[global_r][global_c] = block[lr][2-lc]
            else:
                # Center - original
                result[global_r][global_c] = block[lr][lc]

    return result

